const $=s=>document.querySelector(s);async function call(path,body){let r,d=null;try{r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined})}catch{throw Error('Ingen nettforbindelse. Sjekk nettet og prøv igjen.')}try{d=await r.json()}catch{}if(!r.ok||!d)throw Error((d&&d.error)||'Serveren har problemer akkurat nå. Prøv igjen om litt.');return d}
// Før 7. oktober: passord. 7. oktober til kampdagen tidlig morgen: bibelgåte. Serveren bestemmer hvilken.
// Ingen av tekstene nevner et eksakt klokkeslett -- siden åpner tidlig på kampdagen, det holder å vite det.
const COPY={password:['Skriv inn passordet.','Siden åpner for alle på kampdagen 10. oktober.'],bible:['Finn nøkkelordet.','Vi åpner med et lite bibelspor før turneringen. Svaret skiller ikke mellom store og små bokstaver.']};
call('/api/gate').then(d=>{if(!d.required)return location.replace('/');const [title,intro]=COPY[d.mode]||COPY.bible;$('#gate-title').textContent=title;$('#gate-intro').textContent=intro;$('#gate-question').firstChild.textContent=d.question;$('#gate-answer').type=d.mode==='password'?'password':'text'});
$('#gate-form').onsubmit=async e=>{e.preventDefault();try{await call('/api/gate',{answer:$('#gate-answer').value});location.replace('/')}catch(e){$('#gate-error').textContent=e.message}};$('#gate-admin').onclick=()=>$('#gate-login').showModal();$('.close').onclick=()=>$('#gate-login').close();$('#gate-login-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{await call('/api/login',{username:f.username.value,password:f.password.value});location.replace('/')}catch(e){$('#gate-login-error').textContent=e.message}};
